function matchesSimulationSubject(subjectFilter: SubjectFilter, paperSubject: SubjectFilter) {
  if (subjectFilter === "醫學（一）" || subjectFilter === "醫學（二）") {
    return paperSubject === subjectFilter;
  }

  return true;
}

export function getAISimulationPaperOptions(subjectFilter: SubjectFilter = "全部"): AISimulationPaperOption[] {
  return aiSimulationPapers
    .filter((paper) => matchesSimulationSubject(subjectFilter, paper.subject))
    .map(({ questions, ...paper }) => ({ ...paper, questionCount: questions.length }))
    .sort((left, right) => {
      if ((right.sourceYear ?? 0) !== (left.sourceYear ?? 0)) {
        return (right.sourceYear ?? 0) - (left.sourceYear ?? 0);
      }

      return left.label.localeCompare(right.label);
    });
}

export function getQuestionsForAISimulationPaper(
  paperKey: string,
  subjectFilter: SubjectFilter = "全部"
) {
  const paper = aiSimulationPapers.find(
    (item) => item.key === paperKey && matchesSimulationSubject(subjectFilter, item.subject)
  );

  return [...(paper?.questions ?? [])].sort(
    (left, right) => (left.originalQuestionNumber ?? 0) - (right.originalQuestionNumber ?? 0)
  );
}

export function getAISimulationPaperLabel(
  paperKey: string,
  subjectFilter: SubjectFilter = "全部"
) {
  return getAISimulationPaperOptions(subjectFilter).find((paper) => paper.key === paperKey)?.label;
}
